        slide.addText("HARIOM BUILDS  /  "+clean(course).toUpperCase(),{x:.58,y:7.16,w:9,h:.16,fontFace:"Aptos",fontSize:7,color:C.muted,charSpacing:.7,margin:0});
        slide.addText(String(n).padStart(2,"0"),{x:12.1,y:7.13,w:.55,h:.22,fontFace:"Aptos",fontSize:9,bold:true,color:C.blue,align:"right",margin:0});
