          agenda.addText(String(i+1).padStart(2,"0"),{x:x+.03,y:y+.12,w:.42,h:.16,fontSize:8,bold:true,color:C.blue,align:"center",margin:0});
          agenda.addText(item,{x:x+.65,y:y+.02,w:5.0,h:.4,fontFace:"Aptos",fontSize:12,bold:true,color:C.ink,fit:"shrink",margin:0.02,valign:"middle"});
